#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char **argv)
{
    /* The original binary prints “BALANCED” when no argument is given. */
    const char *input = (argc >= 2) ? argv[1] : "";

    size_t len = strlen(input);
    /* Allocate a stack large enough for the whole string – the original
       program used a fixed‑size array on the stack. */
    char *stack = (char *)malloc(len + 1);
    if (!stack) {
        perror("malloc");
        return 1;
    }

    size_t top = 0;          /* stack pointer */
    int balanced = 1;        /* assume balanced until proven otherwise */

    for (size_t i = 0; i < len && balanced; ++i) {
        char c = input[i];

        /* Push opening delimiters. */
        if (c == '(' || c == '[' || c == '{') {
            stack[top++] = c;
            continue;
        }

        /* Handle closing delimiters. */
        if (c == ')' || c == ']' || c == '}') {
            if (top == 0) {               /* nothing to match */
                balanced = 0;
                break;
            }
            char open = stack[--top];
            if ((c == ')' && open != '(') ||
                (c == ']' && open != '[') ||
                (c == '}' && open != '{')) {
                balanced = 0;             /* mismatched pair */
            }
        }
        /* All other characters are ignored – the original code never
           examined characters other than the six delimiters. */
    }

    /* After processing the whole string the stack must be empty. */
    if (top != 0)
        balanced = 0;

    puts(balanced ? "BALANCED" : "UNBALANCED");

    free(stack);
    return 0;
}
